package com.orderflow.notification.domain;
import static org.assertj.core.api.Assertions.*;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class NotificationDomainTest{@Test void readIsIdempotent(){Notification n=new Notification(UUID.randomUUID(),NotificationType.PAYMENT_SUCCEEDED,"Title","Message",UUID.randomUUID(),UUID.randomUUID(),Instant.EPOCH);assertThat(n.markRead(Instant.EPOCH.plusSeconds(1))).isTrue();assertThat(n.markRead(Instant.EPOCH.plusSeconds(2))).isFalse();assertThat(n.getReadAt()).isEqualTo(Instant.EPOCH.plusSeconds(1));}@Test void preferencesValidateDestinations(){NotificationPreference p=NotificationPreference.defaults(UUID.randomUUID(),Instant.EPOCH);assertThatThrownBy(()->p.update(true,"invalid",false,null,Instant.EPOCH)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->p.update(false,null,true,"123",Instant.EPOCH)).isInstanceOf(IllegalArgumentException.class);p.update(true,"success@example.test",true,"+19990000000",Instant.EPOCH);assertThat(p.isEmailEnabled()).isTrue();assertThat(p.isSmsEnabled()).isTrue();}@Test void deliveryStateIsStrict(){NotificationDelivery d=new NotificationDelivery(UUID.randomUUID(),NotificationChannel.EMAIL,"success@example.test",Instant.EPOCH);d.processing(Instant.EPOCH);d.sent(Instant.EPOCH);assertThat(d.getStatus()).isEqualTo(NotificationDeliveryStatus.SENT);assertThatThrownBy(()->d.processing(Instant.EPOCH)).isInstanceOf(IllegalStateException.class);}}
